public int findLargestSubstring(List<String> strings) {
        int maxLen = 0;
        for (String s : strings) {
            int n = s.length();
            for (int len = n; len > maxLen; len--) {
                for (int i = 0; i <= n - len; i++) {
                    String sub = s.substring(i, i + len);
                    String inv = new StringBuilder(sub).reverse().toString();
                    boolean found = false;
                    for (String t : strings) {
                        if (t.contains(sub) || t.contains(inv)) {
                            found = true;
                            break;
                        }
                    }
                    if (found) {
                        maxLen = len;
                        break;
                    }
                }
            }
        }
        return maxLen;
    }

