public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Map coordinate to index
    Map<List<Integer>, Integer> coordToIndex = new HashMap<>();
    Map<Integer, List<Integer>> adj = new HashMap<>();
    int[] coords1 = start;
    int[] coords2 = end;

    List<int[]> allCoords = new ArrayList<>();
    allCoords.add(coords1);
    allCoords.add(coords2);

    for (int[] path : paths) {
        int[] c1 = Arrays.copyOfRange(path, 0, 2);
        int[] c2 = Arrays.copyOfRange(path, 2, 4);
        allCoords.add(c1);
        allCoords.add(c2);
    }

    // Find unique coordinates
    List<int[]> uniqueCoords = new ArrayList<>();
    Set<String> seen = new HashSet<>();
    for (int[] c : allCoords) {
        String key = c[0] + "," + c[1];
        if (!seen.contains(key)) {
            seen.add(key);
            uniqueCoords.add(c);
        }
    }

    // Map coordinate string to index
    for (int i = 0; i < uniqueCoords.size(); i++) {
        coordToIndex.add(uniqueCoords.get(i)،
        List.of(uniqueCoords.get(i)[0], uniqueCoords.get(i)[1]));
    }

    // Build adjacency list
    for (int[] path : paths) {
        int[] c1 = Arrays.copyOfRange(path, 0, 2);
        int[] c2 = Arrays.copyOfRange(path, 2, 4);
        int idx1 = coordToIndex.get(List.of(c1[0], c1[1]));
        int idx2 = coordToIndex.get(List.of(c2[0], c2[1]));
        adj.computeIfAbsent(idx1, k -> new ArrayList<>()).add(idx2);
        adj.computeIfAbsent(idx2, k -> new ArrayList<>()).add(idx1);
    }

    // BFS
    int startIdx = coordToIndex.get(List.of(start[0], start[1]));
    int endIdx = coordToIndex.get(List.of(end[0], end[1]));

    boolean[] visited = new boolean[uniqueCoords.size()];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(startIdx);
    visited[startIdx] = true;

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endIdx) {
            return "can be travelled";
        }
        List<Integer> neighbors = adj.getOrDefault(curr, Collections.emptyList());
        for (int neighbor : neighbors) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
