    int k = (int) (n * 0.05);
    if (k == 0) {
        double sum = 0;
        for (int x : arr) sum += x;
        return sum / n;
    }
    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    double sum = 0;
    int remaining = n - 2 * k;
    for (int i = k; i < n - k; i++) {
