public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) {
        return false;
    }

    int[] remainderCount = new int[k];

    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        remainderCount[rem]++;
    }

    // Check remainder 0: must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // Check pairs (i, k-i)
    for (int i = 1; i <= k / 2; i++) {
        int j = k - i;
        if (i == j) {
            // For k even, when i == k-i (i.e., i = k/2), count must be even
            if (remainderCount[i] % 2 != 0) {
                return false;
            }
        } else {
            if (remainderCount[i] != remainderCount[j]) {
                return false;
            }
        }
    }

    return true;
}

