public int minOperations(int n) {
    if (n <= 1) return 0;

    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // Target value = average = (sum of arr) / n
    // Sum of arr = sum_{i=0}^{n-1} (2*i+1) = n^2
    // So target = n^2 / n = n
    // We need to make all elements equal to n.

    // Operations needed: sum of positive differences (or equivalently, sum of |arr[i] - n| / 2)
    // Because each operation moves 1 unit from one element above target to one below.
    // Actually, the minimum operations is the sum of (n - arr[i]) for all i where arr[i] < n.

    // arr[i] = 2*i + 1 < n  =>  2*i + 1 < n  =>  i < (n-1)/2

    long operations = 0;
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < n) {
            operations += (n - val);
        }
    }

    return (int) operations;
}

