    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int c = a + b;
        if (c > k) break;
        fibs.add(c);
        a = b;
        b = c;
    }

    // Use greedy approach: take the largest Fibonacci number <= k, subtract it, and repeat
    int count = 0;
    int index = fibs.size() - 1;
    int remaining = k;
    while (remaining > 0) {
        if (fibs.get(index) <= remaining) {
            remaining -= fibs.get(index);
            count++;
        } else {
            index--;
        }
    }
    return count;
}

