public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long higher = n / (factor * 10);
        long current = (n / factor) % 10;
        long lower = n % factor;

        if (current < 1) {
            count += higher * factor;
        } else if (current == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }

        factor *= 10;
    }
    return (int) count;
}

