public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int idx = 0;
    for (int sum = 0; sum <= rows + cols - 2; sum++) {
        if (sum % 2 == 0) {
            // go from bottom to top along the diagonal
            int r = Math.min(sum, rows - 1);
            int c = sum - r;
            while (r >= 0 && c < cols) {
                result[idx++] = mat[r][c];
                r--;
                c++;
            }
        } else {
            // go from top to bottom along the diagonal
            int c = Math.min(sum, cols - 1);
            int r = sum - c;
            while (r < rows && c >= 0) {
                result[idx++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

