public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such digit exists, the number is the largest permutation
    if (i < 0) {
        return -1;
    }

    // Find the smallest digit to the right of i that is greater than digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the suffix after i to get the smallest possible number
    Arrays.sort(digits, i + 1, len);

    // Convert back to integer
    String resultStr = new String(digits);
    try {
        return Integer.parseInt(resultStr);
    } catch (NumberFormatException e) {
        return -1;
    }
}

