public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Check if n is a perfect square
    int sqrtN = (int) Math.sqrt(n);
    if (sqrtN * sqrtN == n) {
        return 1;
    }

    // Check if n is a sum of two perfect squares
    for (int i = 1; i * i <= n; i++) {
        int remaining = n - i * i;
        int j = (int) Math.sqrt(remaining);
        if (j * j == remaining) {
            return 2;
        }
    }

    // Check if n is a sum of three perfect squares using Legendre's three-square theorem
    // A number is not a sum of three squares if it is of the form 4^a(8b+7)
    int temp = n;
    while (temp % 4 == 0) {
        temp /= 4;
    }
    if (temp % 8 != 7) {
        return 3;
    }

    // Otherwise, by the four-square theorem, it must be 4
    return 4;
}

